import{_ as n,a0 as s,w as l,s as i,ao as r,I as a,x as o,a1 as p,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"系統管理員入門：排除故障 | LCTT x X-CMD","titleTemplate":false,"description":"系統管理員入門：排除故障 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"系統管理員入門：排除故障 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"系統管理員入門：排除故障 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20171216 Sysadmin 101- Troubleshooting","title":"系統管理員入門：排除故障","tag":"201908","desc":""},"relativePath":"201908/20171216 Sysadmin 101- Troubleshooting.md","filePath":"[post].md"}'),c={name:"201908/20171216 Sysadmin 101- Troubleshooting.md"};function m(T,e,f,h,u,g){const t=s("Link");return l(),i("div",null,[e[18]||(e[18]=r('<h1 id="系統管理員入門-排除故障" tabindex="-1">系統管理員入門：排除故障 <a class="header-anchor" href="#系統管理員入門-排除故障" aria-label="Permalink to “系統管理員入門：排除故障”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201908/06/100659pox8xkkr8zek888r.jpg" alt=""></p><p>我通常會嚴格保持此Blog的技術性，將觀察、意見等內容保持在最低限度。但是，這篇和接下來的幾篇文章將介紹剛進入系統管理/SRE/系統工程師/sysops/devops-ops（無論你想稱自己是什麼）角色的常見的基礎知識。</p><p>請跟我來！</p><blockquote><p>“我的網站很慢！”</p></blockquote><p>我只是隨機選擇了本文的問題類型，這也可以應用於任何與系統管理員相關的故障排除。我並不是要炫耀那些可以發現最多的信息的最聰明的“金句”。它也不是一個詳盡的、一步步指導的、並在最後一個方框中導向“利潤”一詞的“流程圖”。</p><p>我會通過一些例子展示常規的方法。</p><p>示例場景僅用於説明本文目的。它們有時會做一些不適用於所有情況的假設，而且肯定會有很多讀者在某些時候説“哦，但我覺得你會發現……”。</p><p>但那可能會讓我們錯失重點。</p><p>十多年來，我一直在從事於支持工作，或在支持機構工作，有一件事讓我一次又一次地感到震驚，這促使我寫下了這篇文章。</p><p><strong>有許多技術人員在遇到問題時的本能反應，就是不管三七二十一去嘗試可能的解決方案。</strong></p><p><em>“我的網站很慢，所以”，</em></p><ul><li>我將嘗試增大 <code>MaxClients</code>/<code>MaxRequestWorkers</code>/<code>worker_connections</code></li><li>我將嘗試提升 <code>innodb_buffer_pool_size</code>/<code>effective_cache_size</code></li><li>我打算嘗試啓用 <code>mod_gzip</code>（遺憾的是，這是真實的故事）</li></ul><p><em>“我曾經看過這個問題，它是因為某種原因造成的 —— 所以我估計還是這個原因，它應該能解決這個問題。”</em></p><p>這浪費了很多時間，並會讓你在黑暗中盲目亂撞，胡亂鼓搗。</p><p>你的 InnoDB 的緩衝池也許達到 100％ 的利用率，但這可能只是因為有人運行了一段時間的一次性大型報告導致的。如果沒有排除這種情況，那你就是在浪費時間。</p><h3 id="開始之前" tabindex="-1">開始之前 <a class="header-anchor" href="#開始之前" aria-label="Permalink to “開始之前”">​</a></h3><p>在這裏，我應該説明一下，雖然這些建議同樣適用於許多角色，但我是從一般的支持系統管理員的角度來撰寫的。在一個成熟的內部組織中，或與規模較大的、規範管理的或“企業級”客户合作時，你通常會對一切都進行檢測、測量、繪製、整理（甚至不是文字），併發出警報。那麼你的方法也往往會有所不同。讓我們在這裏先忽略這種情況。</p><p>如果你沒有這種東西，那就隨意了。</p><h3 id="澄清問題" tabindex="-1">澄清問題 <a class="header-anchor" href="#澄清問題" aria-label="Permalink to “澄清問題”">​</a></h3><p>首先確定實際上是什麼問題。“慢”可以是多種形式的。是收到第一個字節的時間嗎？從糟糕的 Javascript 加載和每頁加載要拉取 15 MB 的靜態內容，這是一個完全不同類型的問題。是慢，還是比通常慢？這是兩個非常不同的解決方案！</p><p>在你着手做某事之前，確保你知道實際報告和遇到的問題。找到問題的根源通常很困難，但即便找不到也必須找到問題本身。</p><p>否則，這相當於系統管理員帶着一把刀去參加槍戰。</p><h3 id="唾手可得" tabindex="-1">唾手可得 <a class="header-anchor" href="#唾手可得" aria-label="Permalink to “唾手可得”">​</a></h3><p>首次登錄可疑服務器時，你可以查找一些常見的嫌疑對象。事實上，你應該這樣做！每當我登錄到服務器時，我都會發出一些命令來快速檢查一些事情：我們是否發生了頁交換（<code>free</code> / <code>vmstat</code>），磁盤是否繁忙（<code>top</code> / <code>iostat</code> / <code>iotop</code>），是否有丟包（<code>netstat</code> / <code>proc</code> / <code>net</code> / <code>dev</code>），是否處於連接數過多的狀態（<code>netstat</code>），有什麼東西佔用了 CPU（<code>top</code>），誰在這個服務器上（<code>w</code> / <code>who</code>），syslog 和 <code>dmesg</code> 中是否有引人注目的消息？</p><p>如果你從 RAID 控制器得到 2000 條抱怨直寫式緩存沒有生效的消息，那麼繼續進行是沒有意義的。</p><p>這用不了半分鐘。如果什麼都沒有引起你的注意 —— 那麼繼續。</p><h3 id="重現問題" tabindex="-1">重現問題 <a class="header-anchor" href="#重現問題" aria-label="Permalink to “重現問題”">​</a></h3><p>如果某處確實存在問題，並且找不到唾手可得的信息。</p><p>那麼採取所有步驟來嘗試重現問題。當你可以重現該問題時，你就可以觀察它。<strong>當你能觀察到時，你就可以解決。</strong>如果在第一步中尚未顯現出或覆蓋了問題所在，詢問報告問題的人需要採取哪些確切步驟來重現問題。</p><p>對於由太陽耀斑或只能運行在 OS/2 上的客户端引起的問題，重現並不總是可行的。但你的第一個停靠港應該是至少嘗試一下！在一開始，你所知道的是“某人認為他們的網站很慢”。對於那些人，他們可能還在用他們的 GPRS 手機，也可能正在安裝 Windows 更新。你在這裏挖掘得再深也是浪費時間。</p><p>嘗試重現！</p><h3 id="檢查日誌" tabindex="-1">檢查日誌 <a class="header-anchor" href="#檢查日誌" aria-label="Permalink to “檢查日誌”">​</a></h3><p>我對於有必要包括這一點感到很難過。但是我曾經看到有人在運行 <code>tail /var/log/...</code> 之後幾分鐘就不看了。大多數 *NIX 工具都特別喜歡記錄日誌。任何明顯的錯誤都會在大多數應用程序日誌中顯得非常突出。檢查一下。</p><h3 id="縮小範圍" tabindex="-1">縮小範圍 <a class="header-anchor" href="#縮小範圍" aria-label="Permalink to “縮小範圍”">​</a></h3><p>如果沒有明顯的問題，但你可以重現所報告的問題，那也很棒。所以，你現在知道網站是慢的。現在你已經把範圍縮小到：瀏覽器的渲染/錯誤、應用程序代碼、DNS 基礎設施、路由器、防火牆、網卡（所有的）、以太網電纜、負載均衡器、資料庫、緩存層、會話存儲、Web 服務器軟件、應用程序服務器、內存、CPU、RAID 卡、磁盤等等。</p><p>根據設置添加一些其他可能的罪魁禍首。它們也可能是 SAN，也不要忘記硬件 WAF！以及…… 你明白我的意思。</p><p>如果問題是接收到第一個字節的時間，你當然會開始對 Web 服務器去應用上已知的修復程序，就是它響應緩慢，你也覺得幾乎就是它，對吧？但是你錯了！</p><p>你要回去嘗試重現這個問題。只是這一次，你要試圖消除儘可能多的潛在問題來源。</p><p>你可以非常輕鬆地消除絕大多數可能的罪魁禍首：你能從服務器本地重現問題嗎？恭喜，你剛剛節省了自己必須嘗試修復 BGP 路由的時間。</p><p>如果不能，請嘗試使用同一網絡上的其他計算機。如果可以的話，至少你可以將防火牆移到你的嫌疑人名單上，（但是要注意一下那個交換機！）</p>',41)),a("p",null,[e[1]||(e[1]=o("是所有的連接都很慢嗎？雖然服務器是 Web 服務器，但並不意味着你不應該嘗試使用其他類型的服務進行重現問題。",-1)),p(t,{href:"http://nc110.sourceforge.net/"},{default:d(()=>[...e[0]||(e[0]=[o("netcat",-1)])]),_:1}),e[2]||(e[2]=o(" 在這些場景中非常有用（但是你的 SSH 連接可能會一直有延遲，這可以作為線索）！ 如果這也很慢，你至少知道你很可能遇到了網絡問題，可以忽略掉整個 Web 軟件及其所有組件的問題。用這個知識（我不收 200 美元）再次從頂部開始，按你的方式由內到外地進行！",-1))]),e[19]||(e[19]=r('<p>即使你可以在本地復現 —— 仍然有很多“因素”留下。讓我們排除一些變量。你能用普通文件重現它嗎？ 如果 <code>i_am_a_1kb_file.html</code> 很慢，你就知道它不是資料庫、緩存層或 OS 以外的任何東西和 Web 服務器本身的問題。</p><p>你能用一個需要解釋或執行的 <code>hello_world.(py|php|js|rb..)</code> 文件重現問題嗎？如果可以的話，你已經大大縮小了範圍，你可以專注於少數事情。如果 <code>hello_world</code> 可以馬上工作，你仍然學到了很多東西！你知道了沒有任何明顯的資源限制、任何滿的隊列或在任何地方卡住的 IPC 調用，所以這是應用程序正在做的事情或它正在與之通信的事情。</p><p>所有頁面都慢嗎？或者只是從第三方加載“實時分數數據”的頁面慢？</p><p><strong>這可以歸結為：你仍然可以重現這個問題所涉及的最少量的“因素”是什麼？</strong></p><p>我們的示例是一個緩慢的網站，但這同樣適用於幾乎所有問題。郵件投遞？你能在本地投遞嗎？能發給自己嗎？能發給&lt;常見的服務提供者&gt;嗎？使用小的、純文本的消息進行測試。嘗試直到遇到 2MB 擁堵時。使用 STARTTLS 和不使用 STARTTLS 呢？按你的方式由內到外地進行！</p><p>這些步驟中的每一步都只需要幾秒鐘，遠遠快於實施大多數“可能的”修復方案。</p><h3 id="隔離觀察" tabindex="-1">隔離觀察 <a class="header-anchor" href="#隔離觀察" aria-label="Permalink to “隔離觀察”">​</a></h3><p>到目前為止，當你去除特定組件時無法重現問題時，你可能已經偶然發現了問題所在。</p><p>但如果你還沒有，或者你仍然不知道<strong>為什麼</strong>：一旦你找到了一種方法來重現問題，你和問題之間的“東西”（某個技術術語）最少，那麼就該開始隔離和觀察了。</p><p>請記住，許多服務可以在前台運行和/或啓用調試。對於某些類別的問題，執行此操作通常非常有幫助。</p><p>這也是你的傳統武器庫發揮作用的地方。<code>strace</code>、<code>lsof</code>、<code>netstat</code>、<code>GDB</code>、<code>iotop</code>、<code>valgrind</code>、語言分析器（cProfile、xdebug、ruby-prof ……）那些類型的工具。</p><p>一旦你走到這一步，你就很少能擺脱剖析器或調試器了。</p>',12)),a("p",null,[p(t,{href:"https://linux.die.net/man/1/strace"},{default:d(()=>[...e[3]||(e[3]=[o("strace",-1)])]),_:1}),e[4]||(e[4]=o(" 通常是一個非常好的起點。",-1))]),e[20]||(e[20]=r("<p>你可能會注意到應用程序停留在某個連接到端口 3306 的套接字文件描述符上的特定 <code>read()</code> 調用上。你會知道該怎麼做。</p><p>轉到 MySQL 並再次從頂部開始。顯而易見：“等待某某鎖”、死鎖、<code>max_connections</code> ……進而：是所有查詢？還是隻寫請求？只有某些表？還是隻有某些存儲引擎？等等……</p><p>你可能會注意到調用外部 API 資源的 <code>connect()</code> 需要五秒鐘才能完成，甚至超時。你會知道該怎麼做。</p><p>你可能會注意到，在同一對文件中有 1000 個調用 <code>fstat()</code> 和 <code>open()</code> 作為循環依賴的一部分。你會知道該怎麼做。</p><p>它可能不是那些特別的東西，但我保證，你會發現一些東西。</p><p>如果你只是從這一部分學到一點，那也不錯；學習使用 <code>strace</code> 吧！<strong>真的</strong>學習它，閲讀整個手冊頁。甚至不要跳過歷史部分。<code>man</code> 每個你還不知道它做了什麼的系統調用。98％ 的故障排除會話以 <code>strace</code> 而終結。</p><hr>",7)),a("p",null,[e[6]||(e[6]=o("via: ",-1)),p(t,{href:"http://northernmost.org/blog/troubleshooting-101/index.html"},{default:d(()=>[...e[5]||(e[5]=[o("http://northernmost.org/blog/troubleshooting-101/index.html",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=o("作者：",-1)),p(t,{href:"http://northernmost.org"},{default:d(()=>[...e[7]||(e[7]=[o("Erik Ljungstrom",-1)])]),_:1}),e[11]||(e[11]=o(" 譯者：",-1)),p(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[8]||(e[8]=[o("wxy",-1)])]),_:1}),e[12]||(e[12]=o(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[9]||(e[9]=[o("wxy",-1)])]),_:1})]),a("p",null,[e[15]||(e[15]=o("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[13]||(e[13]=[o("LCTT",-1)])]),_:1}),e[16]||(e[16]=o(" 原創編譯，",-1)),p(t,{href:"https://linux.cn/"},{default:d(()=>[...e[14]||(e[14]=[o("Linux中國",-1)])]),_:1}),e[17]||(e[17]=o(" 榮譽推出",-1))])])}const S=n(c,[["render",m]]);export{x as __pageData,S as default};
